cause.patch:
diff --git a/nginx.conf b/nginx.conf
@@ -25,7 +25,8 @@ server {
     location ~* \.(?:js|css|woff2?|ttf|svg|png|jpe?g|webp|avif|ico)$ { expires 1y; try_files $uri =404; }
     # Fonts keep a stable URL for the preload, so they get a shorter lifetime than hashed bundles.
     location ^~ /fonts/ { expires 30d; try_files $uri =404; }
-    location = /index.html { expires -1; }
+    # Links to /index.html land on the start page; the app router owns every path.
+    location = /index.html { expires -1; rewrite ^ / last; }
     # Must always show the running build; 404 instead of the app when it is missing.
     location = /version.json { expires -1; try_files $uri =404; }
